Method.Source:
/// <summary>
/// Rebate account is already handled from std code when DynamicAccount = METPurchasedFromVendor
/// However, we need to handle the LedgerJournalNameIdRebate
/// </summary>
public void enableFields()
{
    next enableFields();

    // Disable name of journal and make it optional when Purchased from vendor is selected
    if (TAMRebatePosting.RebatePaymentType == TAMRebatePaymentType::Vendor
    &&  TAMRebatePosting.DynamicAccount    == TAMRebateDynamicAccount::METPurchasedFromVendor)
    {
        TAMRebatePosting_ds.object(fieldNum(TAMRebatePosting, LedgerJournalNameIdRebate)).enabled(false);
        TAMRebatePosting_ds.object(fieldNum(TAMRebatePosting, LedgerJournalNameIdRebate)).mandatory(false);
    }
}
